import "dotenv/config";
import { defineConfig } from "prisma/config";

// App runtime uses the pooled DATABASE_URL (serverless-friendly, see src/lib/db.ts).
// The migration/schema engine needs a *direct* connection — Neon's pgbouncer pooler
// breaks the advisory locks migrate relies on. Prefer an explicit DIRECT_URL; else
// derive it by dropping Neon's `-pooler` suffix from the host.
// ponytail: string-strip heuristic, Neon-specific — set DIRECT_URL if your host differs.
const cliUrl =
  process.env["DIRECT_URL"] ??
  process.env["DATABASE_URL"]?.replace("-pooler.", ".");

export default defineConfig({
  schema: "prisma/schema.prisma",
  migrations: {
    path: "prisma/migrations",
    seed: "tsx prisma/seed.ts",
  },
  datasource: {
    url: cliUrl,
  },
});
